const ciReplayDeleteExpired = `-- name: CiReplayDeleteExpired :execrows
DELETE FROM ci_subject_token_uses u
 WHERE (u.issuer_id, u.jti) IN (
        SELECT d.issuer_id, d.jti
          FROM ci_subject_token_uses d JOIN ci_issuers i ON i.id = d.issuer_id
         WHERE d.subject_expires_at < now() - make_interval(secs => $1::bigint::float8)
           AND d.subject_expires_at + i.clock_skew + make_interval(secs => $1::bigint::float8) < now()
         ORDER BY d.subject_expires_at
         LIMIT $2::int)
`

type CiReplayDeleteExpiredParams struct {
	RetentionSecs int64
	MaxRows       int32
}

// ci-replay-cleanup (R-CI-018, R-CI-030): rows whose subject_expires_at + the issuer's clock skew +
// retention_secs has passed, in the order of the expiry index, at most max_rows per transaction.
func (q *Queries) CiReplayDeleteExpired(ctx context.Context, arg CiReplayDeleteExpiredParams) (int64, error) {
	result, err := q.db.Exec(ctx, ciReplayDeleteExpired, arg.RetentionSecs, arg.MaxRows)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

